local BellowsMaker = {}
local PRODUCTS = {
    iron_bellows = { name = "Železni meh za kovaško ognjišče", ironCost = 2, woodCost = 3, leatherCost = 4, time = 6, cost = 195, prestige = 4, happiness = 2, description = "Železni meh za pihanje zraka v kovaško ognjišče." },
    bronze_bellows = { name = "Bronast meh za kovaško ognjišče", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 4, time = 8, cost = 470, prestige = 6, happiness = 3, description = "Bronast meh za močno ognjišče." },
    silver_bellows = { name = "Srebrni meh za kovaško ognjišče", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 4, time = 12, cost = 1130, prestige = 11, happiness = 4, description = "Srebrni meh za plemiške kovače." },
    gilded_bellows = { name = "Pozlačeni meh za kovaško ognjišče", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 16, cost = 2420, prestige = 20, happiness = 5, description = "Pozlačeni meh za dvorne kovače." },
    jewel_set_bellows = { name = "Draguljasti meh za kovaško ognjišče", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 20, cost = 5200, prestige = 36, happiness = 7, description = "Draguljasti meh za kraljevske kovače." },
    royal_sovereign_bellows = { name = "Kraljevski suvereni meh za kovaško ognjišče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 5, time = 27, cost = 11100, prestige = 69, happiness = 13, description = "Suvereni meh z biseri za krono." },
}
local BUILDINGS = {
    bellows_workshop = { name = "Mešna delavnica", cost = { gold = 365, wood = 185, stone = 140, iron = 7 }, upkeep = 7, qualityBonus = 5 },
    bellows_house = { name = "Mešna hiša", cost = { gold = 1275, wood = 370, stone = 285, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_bellows_atelier = { name = "Mojstrski mešni atelje", cost = { gold = 3180, wood = 430, stone = 540, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_bellows_palace = { name = "Suverena mešna palača", cost = { gold = 13700, wood = 660, stone = 865, gold = 89, jewel = 20 }, upkeep = 264, qualityBonus = 55, prestigeBonus = 50 },
}
BellowsMaker.ironStock = 12; BellowsMaker.bronzeStock = 10; BellowsMaker.woodStock = 16; BellowsMaker.leatherStock = 18; BellowsMaker.silverStock = 8; BellowsMaker.goldStock = 6; BellowsMaker.jewelStock = 4; BellowsMaker.pearlStock = 4
BellowsMaker.productStock = {}; BellowsMaker.buildings = {}; BellowsMaker.maker = nil; BellowsMaker.activeMaking = {}; BellowsMaker.totalProducts = 0; BellowsMaker.dayTimer = 0
function BellowsMaker.init() BellowsMaker.ironStock=12; BellowsMaker.bronzeStock=10; BellowsMaker.woodStock=16; BellowsMaker.leatherStock=18; BellowsMaker.silverStock=8; BellowsMaker.goldStock=6; BellowsMaker.jewelStock=4; BellowsMaker.pearlStock=4; BellowsMaker.productStock={}; BellowsMaker.buildings={}; BellowsMaker.maker=nil; BellowsMaker.activeMaking={}; BellowsMaker.totalProducts=0; BellowsMaker.dayTimer=0; print("[BellowsMaker] Royal Bellows Maker System initialized (6 products, 4 buildings)") end
function BellowsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BellowsMaker.maker={name=n or ("Mehar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mehar najet: %s (spretnost: %d)",BellowsMaker.maker.name,s),"success") end; return true end
function BellowsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BellowsMaker.build(id) local ok,e=BellowsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BellowsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BellowsMaker.getQualityBonus() local b=0; for _,bd in ipairs(BellowsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BellowsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BellowsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BellowsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BellowsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BellowsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BellowsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BellowsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BellowsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BellowsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BellowsMaker.buildings==0 then return false,"Potrebna mešna delavnica" end; if not BellowsMaker.maker then return false,"Potreben mehar" end; return true end
function BellowsMaker.make(pt,qty) qty=qty or 1; local ok,e=BellowsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BellowsMaker.ironStock=BellowsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BellowsMaker.bronzeStock=BellowsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BellowsMaker.woodStock=BellowsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BellowsMaker.leatherStock=BellowsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BellowsMaker.silverStock=BellowsMaker.silverStock-d.silverCost*qty end; if d.goldCost then BellowsMaker.goldStock=BellowsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BellowsMaker.jewelStock=BellowsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BellowsMaker.pearlStock=BellowsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BellowsMaker.maker then t=math.max(1,t-math.floor(BellowsMaker.maker.skill/13)) end; table.insert(BellowsMaker.activeMaking,{id="bellows_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BellowsMaker.completeMaking(m) local q=1.0+(BellowsMaker.getQualityBonus()/100); if BellowsMaker.maker then q=q+(BellowsMaker.maker.skill/140) end; q=math.min(2.5,q); BellowsMaker.productStock[m.productType]=(BellowsMaker.productStock[m.productType] or 0)+m.quantity; BellowsMaker.totalProducts=BellowsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BellowsMaker.maker then BellowsMaker.maker.itemsMade=BellowsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BellowsMaker.maker.skill=math.min(100,BellowsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Meh izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bellows.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BellowsMaker.update(dt) if not _G.state then return end; BellowsMaker.dayTimer=BellowsMaker.dayTimer+dt; if BellowsMaker.dayTimer>=30 then BellowsMaker.dayTimer=0; for i=#BellowsMaker.activeMaking,1,-1 do local m=BellowsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BellowsMaker.completeMaking(m); table.remove(BellowsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BellowsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BellowsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BellowsMaker.getStats() return {ironStock=BellowsMaker.ironStock,bronzeStock=BellowsMaker.bronzeStock,woodStock=BellowsMaker.woodStock,leatherStock=BellowsMaker.leatherStock,silverStock=BellowsMaker.silverStock,goldStock=BellowsMaker.goldStock,jewelStock=BellowsMaker.jewelStock,pearlStock=BellowsMaker.pearlStock,productStock=BellowsMaker.productStock,numBuildings=#BellowsMaker.buildings,hasMaker=BellowsMaker.maker~=nil,makerName=BellowsMaker.maker and BellowsMaker.maker.name or "—",makerSkill=BellowsMaker.maker and BellowsMaker.maker.skill or 0,activeMaking=#BellowsMaker.activeMaking,totalProducts=BellowsMaker.totalProducts} end
return BellowsMaker
